\label{main1}
    Let $H$ be a $3$-uniform hypergraph. If $d \geq \frac{3}{2}n^2-\frac{15}{2}n+10$, then: 
    \begin{enumerate}
        \item $L_H^{\mathbb{K}}(d)$ is a radical complete intersection;
        \item $L_H^{\mathbb{K}}(d+1)$ is a prime.
    \end{enumerate}

\label{conj2}
\cite[Conjecture 3.6]{GW2023}
        Let $H=(V, E)$ be a $3$-uniform hypergraph with $n$ vertices. Then $\operatorname{pmd}(H) \leq \frac{3}{2}n^2-\frac{15}{2}n+10$.

\label{thm.goodfor}
    Let $H$ be an $r$-uniform good forest. Then:
    \begin{enumerate}
        \item $L_H^{\mathbb{K}}(d)$ is radical for all $d$.
        \item $L_H^{\mathbb{K}}(d)$ is a complete intersection if and only if $d\geq \Delta(H)$.
        \item $L_H^{\mathbb{K}}(d)$ is prime if $d\geq \Delta(H)+1$.
    \end{enumerate}

\cite[Lemma 5.2]{CW2019}  \label{Rem.pos}
    Let $H = (V, E)$ be a hypergraph, $M \subseteq E$ and $V_M = \cup_{A \in M}A$.    
    \begin{enumerate}[(a)]
        \item $M$ is a positive matching for $H$ if and only if $M$ is a positive matching for the induced hypergraph $(V_M, {A \in E \mid A \subseteq V_M})$.
        \item Assume $M$ is a positive matching on $H$ and $A \in E$ is such that $M_1 = M \cup \{A\}$  is a matching. Assume also that there is a vertex $a \in A$ such that $\{B \in E \mid B \subset V_{M_1}$ and $a \in B\} = \{A\}$. Then $M \cup \{A\}$ is a positive matching of $H$.
    \end{enumerate}

\label{order}
    Let $(l_1,l_2)$ and $(l_1',l_2') \in \mathbb{N}^2$. We say $(l_1,l_2) < (l_1',l_2')$ if 
    \begin{enumerate}[(a)]
        \item $l_1 < l_1'$ or 
        \item $l_1 = l_1'$ and $l_2 < l_2'$.
    \end{enumerate}

We show the pm-decomposition of $H$ by arranging the matching $E_{l_1,l_2}$ in the order defined in Definition \ref{order}. That is, we show a matching $E_{l_1,l_2}$ is a positive matching on $(V,E\setminus \cup_{(l_1',l_2')<(l_1,l_2)} E_{l_1',l_2'})$. 


    If $\lvert E_{l_1,l_2}\rvert = 1$ then it follows from Remark \ref{Rem.pos}(b)  that $E_{l_1,l_2}$ is positive matching on $(V,E\setminus \cup_{(l_1',l_2')<(l_1,l_2)}E_{l_1',l_2'})$. Let $a \in \mathbb{N}$ be an integer and we represent matching $E_{l_1,l_2}$ with $\lvert E_{l_1,l_2}\rvert >1$ in the following form:
    \begin{equation} \label{matrix}
        \begin{bmatrix}
            l_1-l_2+m-a & l_2-m+a & m-a\\
            l_1-l_2+m-a+1 & l_2-m+a-1 & m-a+1\\
            \vdots & \vdots & \vdots \\
            l_1-l_2+m-1 & l_2-m+1 & m-1\\
            l_1-l_2+m & l_2-m & m\\
        \end{bmatrix}
        =
        \begin{bmatrix}
            x_{11} & x_{12} & x_{13}\\
            x_{21} & x_{22} & x_{23}\\
            \vdots & \vdots & \vdots \\
            x_{a1} & x_{a2} & x_{a3}\\
            x_{a+1,1} & x_{a+1,2} & x_{a+1,3}\\
        \end{bmatrix}
    \end{equation}
    where $6\leq m \leq n$, $l_2-m+a < m-a$, $l_1-l_2+m-a \geq 1$. In Equation (\ref{matrix}) each row is an edge of $E_{l_1,l_2}$ (see Remark \ref{form}). We define a map $\rho: V(E_{l_1,l_2}) \rightarrow \mathbb{Q}$ as
    \begin{equation} \label{mapping}
        \begin{split}
            \rho(x_{11})&=t, \ \rho(x_{12})=-(\frac{t}{2} -1), \ \rho(x_{13})=-(\frac{t}{2} -1), \\
            \rho(x_{21})&=-(1+\rho(x_{12})+\rho(x_{13})), \\   \rho(x_{23})&=-(1+\rho(x_{11})+\rho(x_{12})), \\
            \rho(x_{22})&=1-(\rho(x_{21})+\rho(x_{23})), \\
            \rho(x_{i1})&=-(1+\rho(x_{i-1,2})+\rho(x_{i-2,2})), \\ 
            \rho(x_{i3})&=-(1+\rho(x_{i-1,1})+\rho(x_{i-1,2})), \\
            \rho(x_{i2})&=1-(\rho(x_{i1})+\rho(x_{i3})),
        \end{split}
    \end{equation}
    where $3\leq i \leq a+1$, $t \in \mathbb{N}$ such that  $\rho(x_{a+1,1}) > 0$ and $\rho(x_{a+1,2}) \leq 0$.


    To show the existence of such a $t$, first we claim that one can recursively obtain the following forms: $\rho(x_{i1})=t-\alpha_i$, $\rho(x_{i2})=-t/2+\beta_i$ and $\rho(x_{i3})=-t/2-2(i-1)$, where $\alpha_i$ and $\beta_i$ are some positive integers, for all $i>1$. The proof of the claim is by strong induction on $i$. For $i=2$, from Equation (\ref{mapping}) it follows that $\rho(x_{21})=t-3$, $\rho(x_{22})=-t/2+6$ and $\rho(x_{3})=-t/2-2$. Similarly, for $i=3$, it follows from Equation (\ref{mapping}) that $\rho(x_{31})=t-8$, $\rho(x_{32})=-t/2+13$ and $\rho(x_{33})=-t/2-4$. Now, assume the assertion holds for all $i<j$, for some $j\geq 4$. For statement $j$,  it follows from the induction hypothesis and Equation (\ref{mapping})  that $\rho(x_{j1})=t-(\beta_{j-1}+\beta_{j-2}+1)$. From Equation (\ref{eq.a3r}) and induction hypothesis it follows that $\rho(x_{j3})=-t/2-2(j-1)$. From Equation (\ref{mapping}) it follows that  $\rho(x_{j2})=-t/2+(\beta_{i-1}+\beta_{i-2}+2j)$. Hence, the claim is proved for $i=j$. 

    Thus, the conditions $\rho(x_{a+1,1}) > 0$ and $\rho(x_{a+1,2}) \leq 0$ hold if $t\geq 26$ when $a=1,2$, and  $t \geq 2(\beta_{i-1}+\beta_{i-2}+2a)$ when $a>2$.

    Let $E_{l_1,l_2}^c$ be the of set all edges in $(V_{E_{l_1,l_2}},E\setminus \{\cup_{(l_1',l_2')<(l_1,l_2)}E_{l_1',l_2'} \cup E_{l_1,l_2}\})$.
    Observe that $x_{11}<x_{21}< \cdots < x_{a+1,1}<x_{a+1,2}<x_{a2}< \cdots <x_{12}<x_{13} < \cdots <x_{a+1,3}$. From the observation, it follows that 
    \begin{equation*}
        E_{l_1,l_2}^c=
        \begin{cases}
            \{x_{11},x_{12}, \gamma\}, & \gamma=x_{23}, \ldots, x_{a+1,3}, \\
            \{x_{11}, \beta, \gamma\}, & \beta<\gamma, \text{ and } \beta,\gamma \in \{x_{13}, \ldots, x_{a+1,3}\}, \\


            \{x_{i1},x_{i2}, \gamma\}, & 2 \leq i \leq a, \text{ and } \gamma=x_{i+1,3}, \ldots, x_{a+1,3}, \\
            \{x_{i1}, \beta,\gamma\}, & 2 \leq i \leq a+1, \beta<\gamma, \text{ and } \beta,\gamma \in \{x_{i-1,2},\ldots,x_{12},x_{13}, \ldots, x_{a+1,3}\}, \\
            \{\alpha, \beta,\gamma\}, &  \alpha<\beta<\gamma, \text{ and } \alpha,\beta,\gamma \in \{x_{a+1,2},\ldots,x_{12},x_{13}, \ldots, x_{a+1,3}\}.
        \end{cases}
    \end{equation*}
    Clearly, these are all the edges in $E\setminus \{\cup_{(l_1',l_2')<(l_1,l_2)}E_{l_1',l_2'} \cup E_{l_1,l_2}\}$ induced by $V_{E_{l_1,l_2}}$.

    \vspace{2mm}

    From Remark \ref{Rem.pos}(a), it follows that to complete the proof, it is enough to prove the following two claims: 
    \begin{enumerate}
        \item \label{claim1} If $e\in E_{l_1,l_2}$ then $\sum_{i\in e}\rho(i)>0$;
        \item \label{claim2}  If $e'\in E_{l_1,l_2}^c$ then $\sum_{i\in e'}\rho(i)<0$.
    \end{enumerate}
    Claim (\ref{claim1}): From the map $\rho$ $(\ref{mapping})$ it is clear that $\rho(x_{11})+\rho(x_{12})+\rho(x_{13})=2$ and $\rho(x_{i1})+\rho(x_{i2})+\rho(x_{i3})=1$, for all $i=2,\ldots,a+1$. 

    \vspace{1mm}

    Before proving Claim (\ref{claim2}) we show that \begin{multline} \label{ineq}
         \rho(x_{11})> \rho(x_{21})>  \ldots >  \rho(x_{a+1,1})> \\
         \rho(x_{a+1,2})> \rho(x_{a2})>  \ldots > \rho(x_{12})= \rho(x_{13})>  \ldots > \rho(x_{a+1,3}).
    \end{multline}
It is clear that $\rho(x_{12})$ and $\rho(x_{13})$ are equal from the map $\rho$. For all $i=a+1,a,\ldots,3$, one has 
    \begin{equation} \label{eq.a3r}
        \begin{split}
            \rho(x_{i3})&=-1-\rho(x_{i-1,1})+\rho(x_{i-1,2})) \\
            &= -1-\rho(x_{i-1,1})-1+\rho(x_{i-1,1})+\rho(x_{i-1,3}) \\
            &<\rho(x_{i-1,3}).\\
        \end{split}
    \end{equation}
    \text{We have, }
    \begin{equation*} 
        \begin{split}
            \rho(x_{23})&=-1-\rho(x_{11})+\rho(x_{12})=-1-t+\rho(x_{12}) \\
            &<\rho(x_{12})=\rho(x_{13}).
        \end{split}
    \end{equation*}
    From Equation (\ref{mapping}) it follows that 
    \begin{equation*} \label{eq.2r}
    \begin{split}
       \rho(x_{11}) & > -(\rho(x_{12})+\rho(x_{13})) > \rho(x_{21}).\\
        \rho(x_{21}) & > -(\rho(x_{22})+\rho(x_{23})) \\
        & = -\rho(x_{22})-\rho(x_{12})+1+\rho(x_{11})+2\rho(x_{12})) \\
        &= -\rho(x_{22})-\rho(x_{12})+3 >  \rho(x_{31}).\\
    \end{split}
    \end{equation*}
For all $i=4,5, \ldots, a+1$,  one has
    \begin{equation} \label{eq.r1}
    \begin{split}
        \rho(x_{i1})&=-1-\rho(x_{i-1,2})-\rho(x_{i-2,2}) \\
        &= -3+\rho(x_{i-1,1})+\rho(x_{i-1,3})+\rho(x_{i-2,1})+\rho(x_{i-2,3}) \\
        &=\rho(x_{i-1,1}) -4 +\rho(x_{i-2,3})-\rho(x_{i-2,2}). \\
    \end{split}
    \end{equation}
From Equation  (\ref{mapping}) it follows that  $-4 +\rho(x_{2,3})-\rho(x_{2,2}) < 0$. 
Therefore from Equation \ref{eq.r1} we have, $\rho(x_{41})<\rho(x_{31})$. 

Consider the Fibonacci sequence $f_1=1, f_2=2$ and $f_n=f_{n-2}+f_{n-1}$ for all $n>2$. From Equation  (\ref{mapping}) it follows that  $\rho(x_{i-2,3})-\rho(x_{i-2,2}) < -f_{i-2}\rho(x_{11})-f_{i-1}\rho(x_{12})-f_{i-1}\rho(x_{13})<0$, for all $i=5,6,\ldots,a+1$. Thus from Equation (\ref{eq.r1}) we have, $\rho(x_{i1})<\rho(x_{i-1,1})$ for all $i=5,6,\ldots,a+1$. 



Since $\rho(x_{a+1,1}) > 0$ and $\rho(x_{a+1,2}) \leq 0$, one has $\rho(x_{a+1,1})>\rho(x_{a+1,2})$. For all $i= a+1,\ldots,3$, from Equation (\ref{mapping}) we have,
    \begin{equation*}
        \begin{split}
            \rho(x_{i2})&=1-(\rho(x_{i1})+\rho(x_{i3})) \\
            &= 1+1+\rho(x_{i-1,2})+\rho(x_{i-2,2})+1+\rho(x_{i-1,1})+\rho(x_{i-1,2}) \\
            &=3+\rho(x_{i-1,2})+O(i),  \text{ where } O(i)=\rho(x_{i-1,2})+\rho(x_{i-2,2})+\rho(x_{i-1,1}).\\
         \end{split}
    \end{equation*}       
Since $\rho(x_{i-1,2})+\rho(x_{i-2,2}) = - \rho(x_{i1}) -1$  and $\rho(x_{i1}) < \rho(x_{i-1,1})$,  it follows that $O(i)=\rho(x_{i-1,2})+\rho(x_{i-2,2})+\rho(x_{i-1,1}) \geq 0$. Therefore, we get $\rho(x_{i2})>\rho(x_{i-1,2})$. Also, we have
    \begin{equation*}
        \begin{split}
            \rho(x_{22})&=1-(\rho(x_{21})+\rho(x_{23}))\\
            &= 1+1+\rho(x_{12})+\rho(x_{13})+1+\rho(x_{11})+\rho(x_{12})=5+\rho(x_{12}) \\
            &>\rho(x_{12}).\\
        \end{split}
    \end{equation*}
    Hence, Equation (\ref{ineq}) holds.

\vspace{1mm}

    \noindent Claim (\ref{claim2}): First we show that for edges $\{x_{11},x_{12}, \gamma\} \in E_{l_1,l_2}^c$, $\rho(x_{11})+\rho(x_{12})+ \rho(\gamma)<0$, where $\gamma\in \{x_{23}, \ldots, x_{a+1,3}\}$. From the map $\rho$ it follows that $\rho(x_{11})+\rho(x_{12})+ \rho(x_{23})=-1$. From Equation (\ref{ineq}) it follows that $\rho(x_{23})>\rho(j)$, for all $j\in \{x_{33}, \ldots, x_{a+1,3}\}$. Thus $\rho(x_{11})+\rho(x_{12})+\rho(j)<0$, as desired. Similarly, for every edge $\{x_{i1},x_{i2}, \gamma\} \in E_{l_1,l_2}^c$, one has $\rho(x_{i1})+\rho(x_{i2})+ \rho(\gamma)<0$, where $2 \leq i \leq a, \text{ and } \gamma\in \{x_{i+1,3}, \ldots, x_{a+1,3}\}$. From Equations (\ref{ineq}) and (\ref{mapping}) one has $\rho(x_{a+1,2}) \leq 0$, and $\rho(x_{a+1,2}) > \rho(j)$, for all $j\in \{x_{a,2},\ldots,x_{12},x_{13}, \ldots, x_{a+1,3}\}$. Therefore it is clear that for every edge  $\{\alpha, \beta,\gamma\} \in E_{l_1,l_2}^c$, one has  $\rho(\alpha)+ \rho(\beta)+\rho(\gamma)<0$, where $\alpha<\beta<\gamma, \text{ and } \alpha,\beta,\gamma \in \{x_{a+1,2},\ldots,x_{12},x_{13}, \ldots, x_{a+1,3}\}$.

    Next, we show that for edges  $\{x_{11}, \beta, \gamma\} \in E_{l_1,l_2}^c$, $\rho(x_{11})+ \rho(\beta)+ \rho(\gamma) <0$, for all  $\beta<\gamma, \text{ and } \beta,\gamma \in \{x_{13}, \ldots, x_{a+1,3}\}$. From Equation (\ref{mapping}) it follows that $\rho(x_{11})+\rho(x_{13})+\rho(x_{23})=-1$. Then from Equation (\ref{ineq}) one has $\rho(x_{13})+\rho(x_{23})\geq \rho(i)+\rho(j)$, for all $i<j$ and $i,j\in \{x_{13}, \ldots, x_{a+1,3}\}$. Hence we have $\rho(x_{11})+ \rho(\beta)+ \rho(\gamma) <0$ as desired. Similarly, for every edge  $\{x_{i1}, \beta,\gamma\} \in  E_{l_1,l_2}^c$, one has $\rho(x_{i1})+ \rho(\beta)+ \rho(\gamma) <0$, for all  $2 \leq i \leq a+1$, $\beta<\gamma, \text{ and } \beta,\gamma \in \{x_{i-1,2},\ldots,x_{12},x_{13}, \ldots, x_{a+1,3}\}$.  Thus $E_{l_1,l_2}$ is a positive matching on $(V,E\setminus \cup_{(l_1',l_2')<(l_1,l_2)} E_{l_1',l_2'})$ as desired.

First, we fix an order on matching $E_{l_1,\ldots,l_{r-1}}\subset E$. We say $E_{l_1,\ldots,l_{r-1}}<E_{l_1',\ldots,l_{r-1}'}$ if $(l_1,\ldots,l_{r-1})<_{lex}(l_1',\ldots,l_{r-1}')$. Now, we will show the matching $E_{l_1,\ldots,l_{r-1}}$ is a positive matching on $\Lambda=(V,E\setminus \cup_{(l_1',\ldots,l_{r-1}')<_{lex}(l_1,\ldots,l_{r-1})} E_{l_1',\ldots,l_{r-1}'})$ by cardinality of the matching. 

    If $\lvert E_{l_1,\ldots,l_{r-1}}\rvert = 1$ then  from Remark \ref{Rem.pos}(b) it follows that $E_{l_1,\ldots,l_{r-1}}$ is positive matching on $\Lambda$. We depict a matching $E_{l_1,\ldots,l_{r-1}}$ with ($\lvert E_{l_1,\ldots,l_{r-1}}\rvert >1$) using the following representation:

    \textbf{Case I.} For an odd integer $r\geq 5$  we set
    \begin{center}
    \begin{equation*}
        \begin{bmatrix}
            l_1-l_2+l_3-\ldots -l_{r-1}+m-a & \cdots & l_{r-1}-m+a & m-a\\
            l_1-l_2+l_3-\ldots -l_{r-1}+m-a+1 &  \cdots & l_{r-1}-m+a-1 & m-a+1\\
            \vdots & \vdots &  \vdots & \vdots \\
            l_1-l_2+l_3-\ldots -l_{r-1}+m-1 &  \cdots &  l_{r-1}-m+1 & m-1\\
            l_1-l_2+l_3-\ldots -l_{r-1}+m&  \cdots &  l_{r-1}-m & m\\
        \end{bmatrix}
    \end{equation*} 
    \begin{equation*}
        =
        \begin{bmatrix}
            x_{11} &   \cdots & x_{1,r-1} & x_{1r}\\
            x_{21} &  \cdots & x_{2,r-1} & x_{2r}\\
            \vdots &  \vdots & \vdots & \vdots \\
            x_{a1} &  \cdots & x_{3,r-1} & x_{ar}\\
            x_{a+1,1}  & \cdots & x_{a+1,r-1} & x_{a+1,r}\\
        \end{bmatrix} 
    \end{equation*}
    \end{center}
    where, $2r\leq m \leq n$, $a \in \mathbb{N}$ such that  $x_{1,i-1} < 
    x_{1,i}$, $x_{a+1,j-1}<x_{a+1,j}$, and $x_{11} \geq 1$, where $i=3,5,\ldots, r$, and $j=2,4,\ldots,r-1$. In the above representation, each row is an edge of $E_{l_1,\ldots,l_{r-1}}$. Consider the following  ascending sequence:
    \begin{multline} \label{asc.sequ}
        x_{11},x_{21}, \ldots, x_{a+1,1},x_{a+1,2}, x_{a2}, \ldots, x_{12}, x_{13},\\ x_{23}, \dots,x_{a+1,i},
        x_{a+1,i+1}, \dots, x_{1j}, x_{1,j+1}, \ldots, x_{a+1,r},   
    \end{multline}
    where $i=3,5,\ldots,r-2$  and $j=4,6,\ldots,r-1$. We define a map $\phi: V(E_{l_1,\ldots,l_{r-1}}) \rightarrow \mathbb{Q}$ as
    \begin{equation} \label{r-mapping}
        \begin{split}
            \phi(x_{11})&=t,  \\
            \phi(x_{1i})=\phi(x_{1,i+1})&=-(1+\phi(x_{11})+\ldots+\phi(x_{1,i-1})+\phi(\alpha_1)+\ldots+\phi(\alpha_r-i)),\\
        \end{split}
    \end{equation}
where $\alpha_1$  to  $\alpha_{r-i}$ constitute a sequence of  $r-i$ consecutive elements that commence immediately after $x_{1,i+1}$  from Sequence (\ref{asc.sequ}), and $i=2,4,\ldots, r-1$, such that 
    \begin{equation} 
        \begin{split}
            \phi(x_{12})<0& \text{ and } \phi(x_{12})\geq\phi(x_{13})\geq\ldots\geq\phi(x_{1r}) \text{ and }  \phi(x_{11})+\ldots + \phi(x_{1r})=1, \\
            \phi(x_{\ell r})&=-(1+\phi(x_{\ell-1,1})+\ldots+\phi(x_{\ell-1,r-1})), \\
            \phi(x_{\ell k})&=-(1+\phi(x_{\ell 1})+\ldots+\phi(x_{\ell k-1})+\phi({\beta_1})+\ldots+\phi(\beta_{r-k})), \\
        \end{split}
    \end{equation}
where $\beta_1$  to  $\beta_{r-k}$ constitute a sequence of  $r-k$ consecutive elements that commence immediately after $x_{\ell k+1}$  from Sequence (\ref{asc.sequ}), $\phi(x_{\ell,0})=0$, and $1\leq k \leq r-1$,
    \begin{equation*} 
        \begin{split}
            \phi(x_{\ell-1,i})&>\phi(x_{\ell,i}), \text{ where } i=1,3,\ldots,r,  \\ 
            \phi(x_{\ell-1,j})&<\phi(x_{\ell,j}), \text{ where } j=2,4,\ldots,r-1, \\
            \text{ and } \phi(x_{\ell 1})&>\phi(x_{\ell 2})>\ldots>\phi(x_{\ell r}) \text{ such that }  \phi(x_{\ell 1})+\ldots + \phi(x_{\ell r})=1, \\
        \end{split}
    \end{equation*}
    where $2\leq \ell \leq a+1$, $t \gg 0$ such that  $\phi(x_{a+1,1}) > 0$ and $\phi(x_{a+1,2}) \leq 0$.

    The definition of $\phi$ implies that the following sequence is in descending order:
    \begin{multline} \label{dsc.sequ}
        \phi(x_{11}),\phi(x_{21}), \ldots, \phi(x_{a+1,1}),\phi(x_{a+1,2}), \phi(x_{a2}), \ldots, \phi(x_{12}), \phi(x_{13}),\\ \phi(x_{23}), \dots,\phi(x_{a+1,i}), \phi(x_{a+1,i+1}), \dots, \phi(x_{1j}), \phi(x_{1,j+1}), \ldots, \phi(x_{a+1,r}),  
    \end{multline}
    where $i=3,5,\ldots,r-2$  and $j=4,6,\ldots,r-1$.

 \textbf{Case II.} For an even integer $r\geq 4$  we set
    \begin{center}
    \begin{equation*}
        \begin{bmatrix}
            l_1-l_2+l_3-\ldots +l_{r-1}-m & \cdots & l_{r-1}-m & m\\
            l_1-l_2+l_3-\ldots +l_{r-1}-m+1 &  \cdots & l_{r-1}-m+1 & m-1\\
            \vdots & \vdots &  \vdots & \vdots \\
            l_1-l_2+l_3-\ldots +l_{r-1}-m+a-1 &  \cdots &  l_{r-1}-m+a-1 & m-a+1\\
            l_1-l_2+l_3-\ldots +l_{r-1}-m+a&  \cdots &  l_{r-1}-m+a & m-a\\
        \end{bmatrix}
    \end{equation*} 
    \begin{equation*}
        =
        \begin{bmatrix}
            x_{11} &   \cdots & x_{1,r-1} & x_{1r}\\
            x_{21} &  \cdots & x_{2,r-1} & x_{2r}\\
            \vdots &  \vdots & \vdots & \vdots \\
            x_{a1} &  \cdots & x_{3,r-1} & x_{ar}\\
            x_{a+1,1}  & \cdots & x_{a+1,r-1} & x_{a+1,r}\\
        \end{bmatrix} 
    \end{equation*}
    \end{center}
    where, $2r\leq m \leq n$, $a \in \mathbb{N}$ such that  $x_{1,i-1} < 
    x_{1,i}$, $x_{a+1,j-1}<x_{a+1,j}$, and $x_{11} \geq 1$, where $i=3,5,\ldots,r-1$, and $j=2,4,\ldots,r$. In the above representation, each row is an edge of $E_{l_1,\ldots,l_{r-2}}$. Consider the following  ascending sequence:
    \begin{multline} \label{2asc.sequ}
        x_{11},x_{21}, \ldots, x_{a+1,1},x_{a+1,2}, x_{a2}, \ldots, x_{12}, x_{13},\\ x_{23}, \dots,x_{a+1,i},
        x_{a+1,i+1}, \dots, x_{1j}, x_{1,j+1}, \ldots, x_{a+1,r-1}, x_{a+1,r},\ldots, x_{1,r},   
    \end{multline}
    where $i=3,5,\ldots,r-3$  and $j=4,6,\ldots,r-2$. We define a map $\psi: V(E_{l_1,\ldots,l_{r-1}}) \rightarrow \mathbb{Q}$ as
     \begin{equation} \label{r2-mapping}
        \begin{split}
            \psi(x_{11})&=t,  \\
            \psi(x_{1i})=\psi(x_{1,i+1})&=-(1+\psi(x_{11})+\ldots+\psi(x_{1,i-1})+\psi(\alpha_1)+\ldots+\psi(\alpha_r-i)),\\
        \end{split}
    \end{equation}
where $\alpha_1$  to  $\alpha_{r-i}$ constitute a sequence of  $r-i$ consecutive elements that commence immediately after $x_{1,i+1}$  from Sequence (\ref{2asc.sequ}), and $i=2,4,\ldots, r-2$, such that 
