        \begin{split}
            \psi(x_{12})<0& \text{ and } \psi(x_{12})\geq\psi(x_{13})\geq\ldots\geq\psi(x_{1r}) \text{ and }  \psi(x_{11})+\ldots + \psi(x_{1r})=1, \\
            \psi(x_{m r})&=-(1+\psi(x_{m+1,1})+\ldots+\psi(x_{m+1,r-1})), \text{ where } m=1,\ldots,a,\\
            \psi(x_{\ell k})&=-(1+\psi(x_{\ell 1})+\ldots+\psi(x_{\ell k-1})+\psi({\beta_1})+\ldots+\psi(\beta_{r-k})), \\
        \end{split}
    \end{equation}
where $\beta_1$  to  $\beta_{r-k}$ constitute a sequence of  $r-k$ consecutive elements that commence immediately after $x_{\ell k+1}$  from Sequence (\ref{2asc.sequ}), $\psi(x_{\ell,0})=0$, and $1\leq k \leq r-1$,
    \begin{equation*} 
        \begin{split}
            \psi(x_{\ell-1,i})&>\psi(x_{\ell,i}), \text{ where } i=1,3,\ldots,r-1,  \\
            \psi(x_{\ell-1,j})&<\psi(x_{\ell,j}), \text{ where } j=2,4,\ldots,r, \\
            \text{ and } \psi(x_{\ell 1})&>\psi(x_{\ell 2})>\ldots>\psi(x_{\ell r}) \text{ such that }  \psi(x_{\ell 1})+\ldots + \psi(x_{\ell r})=1, \\
        \end{split}
    \end{equation*}
    where $2\leq \ell \leq a+1$, $t \gg 0$ such that  $\psi(x_{a+1,1}) > 0$ and $\psi(x_{a+1,2}) \leq 0$.  

