\label{thm.r-uni}
    Let $H=(V,E)$ be an $r$-uniform hypergraph and $M \subset E$ be a matching. The following conditions are equivalent:
    \begin{enumerate}
        \item $M$ is positive;
        \item The subgraph induced by $M$ does not contain any strong alternate closed walk;
        \item The subgraph induced by every subset $V(N) \subseteq V(M)$ does not contain any subgraph $N_1 \subseteq H[V(N)]$ such that $N \subseteq N_1$ and $\deg_{N_1}(u_{i1}) =\deg_{N_1}(u_{i2})=\ldots=\deg_{N_1}(u_{ir})= k$, where $k\geq 2$ for all $\{u_{i1},\ldots,u_{ir}\} \in N$.  
    \end{enumerate}

Let $H=(V,E)$ be an $r$-uniform hypergraph on $[n]$. Then $H$ is called 
    \begin{enumerate}
        \item \textit{good forest} if there exist a sequence of edges $e_1,\dots,e_m$ such that $\lvert V_{\{e_1,\ldots,e_i\}}\cap V_{e_{i+1}}\rvert \leq 1$, for all $1\leq i \leq m-1$, where $m=\lvert E\rvert$. We call it a good tree if $H$ is connected.
        \item \textit{loose cycle} if $E=\{\{1,\dots,r\},\{r,\dots,2r-1\},\ldots,\{n-r-2,\dots,n,1\}\}$, denote it by $C_{(r-1)m}$, where $m>1$ and $(r-1)m=n$.
    \end{enumerate}
